 * <script>
 * async function createPdf(docDefinition, tableLayouts, fonts) {
 *   return new Promise((resolve) => {
 *     pdfMake.createPdf(docDefinition, tableLayouts, fonts).getBlob(resolve);
 *   });
 * }
